  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "MW150, a piperazine-containing heteroaryl with fluorophenyl and extended aromatic substituents, showed a brain/plasma ratio >0.9 in rats, directly supporting CNS distribution for piperazine-linked heteroaromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "An ethyl-piperazine biarylamide analogue traversed the BBB and produced excellent mouse brain drug levels after oral dosing, supporting CNS access for ethyl-piperazine-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A piperazine-substituted pyridin-2-one showed a brain/plasma ratio of 3.7 in rats, demonstrating good brain penetration despite a basic piperazine moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "NNC 12-0722, a lipophilic piperazine/fluorophenyl ether, rapidly accumulated in monkey brain after intravenous injection, supporting meaningful brain uptake for similar low-TPSA piperazines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NS-7, a fluorophenyl-substituted heteroaromatic with a basic amine side chain, reached high brain tissue levels after peripheral administration, supporting CNS access for this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: The query is a lipophilic, low-TPSA ethylpiperazine heteroaryl with favorable passive BBB properties, and multiple structurally related piperazine/fluorophenyl heteroaromatics show direct in vivo brain penetration. No strong contradictory evidence applies.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule; all evidence is from analogues with Morgan similarity below 0.31.",
    "Efflux transporter (e.g., P-gp/BCRP) substrate status of the query is not experimentally characterized.",
    "Unbound brain concentration and functional CNS target engagement were not measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

